// Checks DocChat's signature: HMAC-SHA256 of the exact raw body with the
// webhook secret, plus a 5 minute window on the timestamp against replays.
const crypto = require('crypto');
const secret = $('Start eval').first().json.data.callback_secret;
const item = $input.first();
const headers = item.json.headers || {};
let raw = '';
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
}
const signature = String(headers['x-docchat-signature'] || '');
const timestamp = String(headers['x-docchat-timestamp'] || '');
const expected = 'sha256=' + crypto.createHmac('sha256', String(secret || '')).update(raw).digest('hex');
let body = null;
try { body = JSON.parse(raw); } catch (error) { body = null; }
const fresh = /^\d+$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
const valid = Boolean(secret)
  && signature.length === expected.length
  && crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))
  && fresh
  && body !== null
  && String(body.timestamp) === timestamp;

const run = valid ? body.data.eval_run : null;
const pct = (value) => (value === null || value === undefined ? '-' : `${Math.round(value * 100)}%`);
let subject;
let text;

if (!item.json.headers) {
  subject = 'DocChat eval: no result after 2 hours';
  text = `Eval run ${$('Start eval').first().json.data.id} did not report back. Check the worker logs.`;
} else if (!valid) {
  subject = 'DocChat eval: callback signature did not match';
  text = 'A request reached the eval callback without a valid signature. It was ignored.';
} else {
  const s = run.summary || {};
  subject = `DocChat eval ${run.status}: hit rate ${pct(s.retrieval_hit_rate)}, keywords ${pct(s.keyword_match_rate)}`;
  const misses = (run.results || [])
    .filter((r) => r.error || (r.should_refuse ? !r.refused : !r.hit))
    .map((r) => `- ${r.question} (${r.error ? 'error: ' + r.error : r.should_refuse ? 'answered, should refuse' : 'expected page not retrieved'})`);
  text = [
    `Run ${run.id}: ${run.completed_cases} of ${run.cases} cases.`,
    '',
    `Retrieval hit rate: ${pct(s.retrieval_hit_rate)}`,
    `Keyword match rate: ${pct(s.keyword_match_rate)}`,
    `Correct refusals: ${pct(s.correct_refusal_rate)}`,
    `Wrong refusals: ${pct(s.false_refusal_rate)}`,
    `Average latency: ${s.avg_latency_ms ?? '-'} ms, total tokens: ${s.total_tokens ?? '-'}, errors: ${s.errors ?? 0}`,
    run.error ? `\nThe run failed: ${run.error}` : '',
    misses.length ? '\nMisses:\n' + misses.join('\n') : '\nNo misses.',
  ].join('\n');
}

return [{ json: { valid, subject, text } }];
